def find_project_root() -> Path:
    """Find Sergio_Knowledge_OS_APP in current or parent directories."""
    current = Path.cwd().resolve()
    for path in [current] + list(current.parents):
        candidate = path / "Sergio_Knowledge_OS_APP"
        if candidate.is_dir():
            return candidate
        if path.name == "Sergio_Knowledge_OS_APP":
            return path
    fallback = current / "Sergio_Knowledge_OS_APP"
    print(f"WARNING: Project root not found. Creating: {fallback}")
    return fallback


def write_file(root: Path, relative_path: str, content: bytes) -> None:
    """Write a file, creating parent directories if needed."""
    file_path = root / relative_path
    file_path.parent.mkdir(parents=True, exist_ok=True)
    file_path.write_bytes(content)
    print(f"  OK {relative_path}")


def clean_cache(root: Path) -> None:
    """Remove __pycache__ and .pyc files."""
    removed = 0
    for pycache in root.rglob("__pycache__"):
        if pycache.is_dir():
            shutil.rmtree(pycache)
            removed += 1
    for pyc in root.rglob("*.pyc"):
        pyc.unlink()
        removed += 1
    if removed:
        print(f"  CLEANED {removed} cache items")


def run_tests(root: Path) -> dict:
    """Run pytest and verify scripts."""
    results = {"pytest_m2": None, "pytest_m3": None, "verify_m2": None, "verify_m3": None}

    print("\n  RUNNING pytest M2...")
    pytest_m2 = subprocess.run(
        [sys.executable, "-m", "pytest", "tests/test_config.py", "tests/test_parsers.py", "tests/test_import_manager.py", "-v", "--tb=short"],
        cwd=root, capture_output=True, text=True
    )
    results["pytest_m2"] = pytest_m2.returncode == 0
    if results["pytest_m2"]:
        passed = pytest_m2.stdout.count("PASSED")
        print(f"    PASS pytest M2: {passed} tests")
    else:
        print(f"    FAIL pytest M2")
        print(pytest_m2.stdout[-500:] if len(pytest_m2.stdout) > 500 else pytest_m2.stdout)

    print("\n  RUNNING pytest M3...")
    pytest_m3 = subprocess.run(
        [sys.executable, "-m", "pytest", 
         "tests/test_database_layer.py", "tests/test_repositories.py",
         "tests/test_knowledge_engine.py", "tests/test_db_import_pipeline.py",
         "-v", "--tb=short"],
        cwd=root, capture_output=True, text=True
    )
    results["pytest_m3"] = pytest_m3.returncode == 0
    if results["pytest_m3"]:
        passed = pytest_m3.stdout.count("PASSED")
        print(f"    PASS pytest M3: {passed} tests")
    else:
        print(f"    FAIL pytest M3")
        print(pytest_m3.stdout[-500:] if len(pytest_m3.stdout) > 500 else pytest_m3.stdout)

    print("\n  RUNNING verify_milestone2.py...")
    verify_m2 = subprocess.run([sys.executable, "verify_milestone2.py"], cwd=root, capture_output=True, text=True)
    results["verify_m2"] = verify_m2.returncode == 0
    if results["verify_m2"]:
        print(f"    PASS verify_milestone2.py: 6/6 PASS")
    else:
        print(f"    FAIL verify_milestone2.py")
        print(verify_m2.stdout[-500:] if len(verify_m2.stdout) > 500 else verify_m2.stdout)

    print("\n  RUNNING verify_milestone3.py...")
    verify_m3 = subprocess.run([sys.executable, "verify_milestone3.py"], cwd=root, capture_output=True, text=True)
    results["verify_m3"] = verify_m3.returncode == 0
    if results["verify_m3"]:
        print(f"    PASS verify_milestone3.py: 6/6 PASS")
    else:
        print(f"    FAIL verify_milestone3.py")
        print(verify_m3.stdout[-500:] if len(verify_m3.stdout) > 500 else verify_m3.stdout)

    return results


